Extract the values from this document as JSON conforming exactly to this schema. Use null for fields not present on the page. Output only JSON.

Schema:
{
  "type": "object",
  "title": "Workforce By Employment & Gender",
  "required": [
    "topWorkforceSector",
    "workforceByGender"
  ],
  "properties": {
    "figures": {
      "type": "array",
      "description": "One entry per figure printed on the page, in page order",
      "items": {
        "type": "object",
        "properties": {
          "figureNumber": {
            "type": "string",
            "description": "Figure label as printed, e.g. 'Figure 20'"
          },
          "title": {
            "type": "string",
            "description": "Figure title as printed, excluding the figure label"
          },
          "chartType": {
            "type": "string"
          },
          "yAxisMax": {
            "type": "number",
            "description": "Highest printed y-axis tick"
          },
          "yAxisLabels": {
            "type": "array",
            "items": {
              "type": "string"
            },
            "description": "Y-axis tick labels as printed, bottom to top"
          },
          "xAxisLabels": {
            "type": "array",
            "items": {
              "type": "string"
            },
            "description": "X-axis category labels as printed, left to right"
          },
          "legend": {
            "type": "array",
            "items": {
              "type": "string"
            },
            "description": "Legend entries as printed, in legend order"
          },
          "legendNote": {
            "type": [
              "string",
              "null"
            ],
            "description": "Any key printed beneath the legend, null if absent"
          }
        }
      }
    },
    "employmentLevelBreakdown": {
      "type": "array",
      "description": "Figure 20: headcount for each employment level in each year",
      "items": {
        "type": "object",
        "required": [
          "level"
        ],
        "properties": {
          "level": {
            "type": "string"
          },
          "values": {
            "type": "array",
            "items": {
              "type": "object",
              "properties": {
                "year": {
                  "type": "number"
                },
                "headcount": {
                  "type": "number"
                }
              }
            }
          }
        }
      }
    },
    "ageAndGenderBreakdown": {
      "type": "array",
      "description": "Figure 21: headcount by age band for each year and gender, one entry per bar",
      "items": {
        "type": "object",
        "required": [
          "year",
          "gender"
        ],
        "properties": {
          "year": {
            "type": "number"
          },
          "gender": {
            "type": "string"
          },
          "bands": {
            "type": "array",
            "items": {
              "type": "object",
              "properties": {
                "ageBand": {
                  "type": "string",
                  "description": "Age band label as printed in the legend"
                },
                "headcount": {
                  "type": "number"
                }
              }
            }
          },
          "total": {
            "type": "number"
          }
        }
      }
    },
    "workforceByGender": {
      "type": "array",
      "description": "Data on the workforce split by gender, listed by year. Round all numbers to the nearest thousand.",
      "items": {
        "type": "object",
        "required": [
          "year",
          "male",
          "female"
        ],
        "properties": {
          "male": {
            "type": "number",
            "description": "Number of male employees in that year rounded to nearest thousand (i.e. 1,234 should be 1000)."
          },
          "year": {
            "type": "number",
            "description": "Four-digit year"
          },
          "female": {
            "type": "number",
            "description": "Number of female employees in that year rounded to nearest thousand (i.e. 8,904 should be 9000)."
          }
        }
      }
    },
    "topWorkforceSector": {
      "type": "string",
      "description": "The largest employment category (e.g. Sales, Operations, Finance, etc.)"
    },
    "pageNumber": {
      "type": "string"
    },
    "documentFooter": {
      "type": "string"
    }
  }
}

